use eframe::egui;

/// The mascot icon (ink face crop, generated by `scripts/generate_brand_art.ps1`).
fn app_icon() -> egui::IconData {
    eframe::icon_data::from_png_bytes(include_bytes!("../../assets/brand/thme-icon-256.png"))
        .unwrap_or_default()
}

/// Launch the THME native desktop GUI by Epiphanes
pub fn launch_gui() -> anyhow::Result<()> {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1380.0, 880.0])
            .with_min_inner_size([1100.0, 700.0])
            .with_icon(std::sync::Arc::new(app_icon()))
            .with_title("THME Studio // Epiphanes Topological Heterogeneous Manifold Engine"),
        ..Default::default()
    };

    eframe::run_native(
        "THME Studio",
        options,
        Box::new(|cc| Ok(Box::new(THMEApp::new(cc)))),
    )
    .map_err(|e| anyhow::anyhow!("Failed to run GUI: {}", e))
}
